from pathlib import Path
from playwright.sync_api import sync_playwright
import json, shutil
root=Path(__file__).resolve().parents[1];out=root/'tests' / 'generated';screens=out/'Prototype_screenshots';screens.mkdir(parents=True,exist_ok=True)
results=[]
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=shutil.which('chromium'),headless=True);page=b.new_page(viewport={'width':1440,'height':1000},device_scale_factor=1)
 errors=[];page.on('pageerror',lambda err:errors.append(str(err)));page.set_content((root/'prototype/index.html').read_text())
 def screen(name):page.screenshot(path=str(screens/(name+'.png')),full_page=True)
 def nav(name):page.locator(f'[data-page="{name}"]').click()
 def click(id):page.locator('#'+id).click()
 def login(role):nav('auth');page.select_option('#persona',role);click('startAuth');page.fill('#code','246810');click('verify')
 def test(id,condition,observed):results.append({'test':id,'result':'PASS' if condition else 'FAIL','observed':observed});assert condition,id
 screen('01_Authentication');page.select_option('#persona','Examiner');click('startAuth');page.fill('#code','111111');click('verify');test('T01 Invalid demo MFA', 'failed' in page.locator('#authStatus').inner_text(),page.locator('#authStatus').inner_text());page.fill('#code','246810');click('verify');nav('examiner');click('submitQuestion');click('approveQuestion');test('T02 Examiner self-approval blocked','Denied' in page.locator('#questionStatus').inner_text(),page.locator('#questionStatus').inner_text());screen('03_Examiner_portal');login('Moderator');nav('examiner');click('approveQuestion');test('T03 Independent question approval',page.locator('#questionState').inner_text()=='Approved',page.locator('#questionState').inner_text())
 login('Student');nav('student');click('early');test('T04 Early exam access blocked','Denied' in page.locator('#studentStatus').inner_text(),page.locator('#studentStatus').inner_text());screen('02_Student_dashboard');click('enterExam');page.fill('#answer','Independent approval reduces unilateral grade changes.');click('save');click('submit');test('T05 Submission receipt','ES-R001' in page.locator('#examStatus').inner_text(),page.locator('#examStatus').inner_text());click('submit');test('T06 Duplicate submission handled','no duplicate' in page.locator('#examStatus').inner_text(),page.locator('#examStatus').inner_text());screen('04_Examination');login('Examiner');nav('results');click('recordMark');click('publish');test('T07 Examiner cannot publish','Denied' in page.locator('#gradeStatus').inner_text(),page.locator('#gradeStatus').inner_text());screen('05_Results_management');login('Registrar');nav('results');click('publish');test('T08 Registrar cannot bypass moderation','Moderation must occur first' in page.locator('#gradeStatus').inner_text(),page.locator('#gradeStatus').inner_text());login('Moderator');nav('results');click('moderate');login('Registrar');nav('results');click('publish');test('T09 Independent publication',page.locator('#gradeState').inner_text()=='Published',page.locator('#gradeState').inner_text());login('Security analyst');nav('security');click('inject');test('T10 Simulated alert','ES-INC-01' in page.locator('#securityStatus').inner_text(),page.locator('#securityStatus').inner_text());test('T11 Denials audited',int(page.locator('#deniedCount').inner_text())>=4,page.locator('#deniedCount').inner_text()+' denied events');screen('06_Security_dashboard');test('T12 Browser errors absent',not errors,str(errors));click('reset');test('T13 Reset clears state',page.locator('#roleDisplay').inner_text()=='Not signed in',page.locator('#roleDisplay').inner_text());b.close()
(out/'Prototype_test_results.json').write_text(json.dumps({'scope':'Automated browser interaction tests on offline mock UI only; no security assurance or production validation.','results':results},indent=2))
(out/'Prototype_test_results.md').write_text('# Prototype browser verification\n\nScope: automated Chromium interaction tests on the offline mock UI. These do not verify production security, persistence, encryption, availability, tenant isolation or GDPR compliance.\n\n| Test | Result | Observed |\n|---|---|---|\n'+'\n'.join('| '+r['test']+' | '+r['result']+' | '+r['observed'].replace('|','/')+' |' for r in results)+'\n')
print(len(results),'passed')
